#include "opensim/framework/asset_nrbf.hpp"
#include <iostream>
#include <sstream>
using namespace opensim::framework;
namespace {
std::string hex(std::span<const std::uint8_t> bytes){std::string out;for(auto b:bytes){out+="0123456789abcdef"[b>>4];out+="0123456789abcdef"[b&15];}return out;}
std::string text(const std::optional<std::string>& s){return !s?"n":"s"+hex(std::span(reinterpret_cast<const std::uint8_t*>(s->data()),s->size()));}
std::string bytes(const AssetBytes& b){return !b?"n":"b"+hex(*b);}
std::vector<std::uint8_t> unhex(std::string_view text){if(text.size()%2)throw std::invalid_argument("hex");std::vector<std::uint8_t> out;auto digit=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::invalid_argument("hex");};for(std::size_t i=0;i<text.size();i+=2)out.push_back(static_cast<std::uint8_t>(digit(text[i])*16+digit(text[i+1])));return out;}
std::string snapshot(const AssetBase& a){auto result=bytes(a.data)+"|"+std::to_string(a.upload_attempts)+"|";auto m=a.metadata();if(!m)return result+"META_NULL";return result+m->full_id().str()+"|"+text(m->raw_id())+"|"+text(m->name)+"|"+text(m->description)+"|"+text(m->creator_id)+"|"+std::to_string(m->type)+"|"+text(m->raw_content_type())+"|"+std::to_string(m->creation_date.serialized_data())+"|"+bytes(m->sha1)+"|"+(m->local?"1":"0")+(m->temporary?"1":"0")+"|"+std::to_string(m->flags)+"|"+(a.data==m->sha1?"1":"0");}
}
int main(int argc,char**argv){try{if(argc>1&&std::string_view(argv[1])=="--probe"){std::string line;while(std::getline(std::cin,line)){try{auto split=line.find(' ');auto op=line.substr(0,split);auto data=unhex(line.substr(split+1));std::shared_ptr<AssetBase> asset;bool ok=op=="legacy"?AssetNrbfCodec::decode_legacy(data,asset):AssetNrbfCodec::decode_file(data,asset);if(!ok){std::cout<<"ERR\n";continue;}if(op=="transcode")std::cout<<hex(AssetNrbfCodec::encode(*asset))<<'!';std::cout<<snapshot(*asset)<<'\n';}catch(...){std::cout<<"ERR\n";}}return 0;}
 AssetBase a(Uuid("12345678-9abc-4def-8123-000000000001"),"Native asset",std::int8_t(7),"creator");a.data=std::make_shared<std::vector<std::uint8_t>>(std::initializer_list<std::uint8_t>{0,255,1});a.metadata()->sha1=a.data;a.upload_attempts=19;a.metadata()->creation_date=AssetDateTime::from_serialized(0xc000000000000123ull);auto encoded=AssetNrbfCodec::encode(a);std::shared_ptr<AssetBase> result;if(!AssetNrbfCodec::decode_file(encoded,result)||snapshot(a)!=snapshot(*result)||result->data!=result->metadata()->sha1)throw std::runtime_error("NRBF private fields/alias roundtrip");if(!AssetNrbfCodec::decode_legacy(encoded,result)||result->upload_attempts!=0||result->metadata()->sha1||result->metadata()->creation_date.serialized_data()!=0x8000000000000123ull)throw std::runtime_error("Original legacy decoder omissions/DateTime normalization");for(std::size_t n=0;n<encoded.size();++n)if(AssetNrbfCodec::decode_file(std::span(encoded).first(n),result))throw std::runtime_error("Truncation accepted");std::cout<<"PASS: asset NRBF native fields/alias/date/truncation checks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
